// ---- Helpers: keep these. The tests use ListNode, fromArray and toArray. ----
class ListNode {
  constructor(val, next = null) {
    this.val = val;
    this.next = next;
  }
}

// fromArray([1, 2, 3]) builds 1 -> 2 -> 3 and returns the head (null for []).
function fromArray(values) {
  let head = null;
  for (let i = values.length - 1; i >= 0; i--) {
    head = new ListNode(values[i], head);
  }
  return head;
}

// toArray(head) walks the list and returns [1, 2, 3]. Handy for console.log too.
function toArray(head) {
  const values = [];
  let node = head;
  while (node) {
    values.push(node.val);
    if (values.length > 10000) throw new Error('list is too long: did you accidentally create a cycle?');
    node = node.next;
  }
  return values;
}
// ---- End of helpers ----

function mergeTwoLists(list1, list2) {
  const dummy = new ListNode(0); // placeholder so we never special-case "the first node"
  let tail = dummy;
  let a = list1;
  let b = list2;
  while (a !== null && b !== null) {
    if (a.val <= b.val) {
      tail.next = a;
      a = a.next;
    } else {
      tail.next = b;
      b = b.next;
    }
    tail = tail.next;
  }
  // One list ran out: attach whatever is left of the other (already sorted).
  tail.next = a !== null ? a : b;
  return dummy.next;
}

